  var server=h.getLevel().getServer();var store=CommerceService.store(server);var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),id,"ThirdStudent");var proof=server.getWorldPath(LevelResource.ROOT).resolve("library-spell-catalogue-test.nbt");var project=LibraryServiceRuntime.project(p);LibraryGlyphCatalogueRuntime.verifyIrons(h,p);var home=h.getLevel().getEntity(project.npc()).blockPosition();
