 static ItemStack raw(String id,int level)throws Exception{var spell=Class.forName("io.redspace.ironsspellbooks.api.spells.AbstractSpell");var registry=Class.forName("io.redspace.ironsspellbooks.api.registry.SpellRegistry");var value=registry.getMethod("getSpell",String.class).invoke(null,"irons_spellbooks:"+id);var stack=new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse("irons_spellbooks:scroll")));Class.forName("io.redspace.ironsspellbooks.api.spells.ISpellContainer").getMethod("createScrollContainer",spell,int.class,ItemStack.class).invoke(null,value,level,stack);return stack;}
